import { mkdir, readdir, readFile, unlink, writeFile } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { optimize } from 'svgo';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const source = join(root, 'node_modules/disarto-icons-static/icons');
const destination = join(root, 'resources/svg');
const icons = [];
const filenames = new Set();
const cases = new Set();

// Prepare every output before changing the generated files.
for (const variant of ['regular', 'solid']) {
    const directory = join(source, variant);
    const files = (await readdir(directory, { withFileTypes: true }))
        .filter((file) => file.isFile() && file.name.endsWith('.svg'))
        .map((file) => file.name)
        .sort();

    if (files.length === 0) {
        throw new Error(`No SVG icons found in ${directory}`);
    }

    for (const file of files) {
        const name = file.slice(0, -4) + (variant === 'solid' ? '-solid' : '');
        const caseName = name.split('-').map((part) => part.charAt(0).toUpperCase() + part.slice(1)).join('');

        if (!/^[a-z][a-z0-9-]*$/.test(name) || !/^[A-Z][A-Za-z0-9]*$/.test(caseName)) {
            throw new Error(`Cannot generate a PHP enum case for ${file}`);
        }

        if (filenames.has(name) || cases.has(caseName.toLowerCase())) {
            throw new Error(`Duplicate output filename or enum case for ${variant}/${file}`);
        }

        filenames.add(name);
        cases.add(caseName.toLowerCase());

        const path = join(directory, file);
        const svg = optimize(await readFile(path, 'utf8'), {
            path,
            multipass: true,
            plugins: ['preset-default'],
        }).data;

        icons.push({ name, caseName, svg });
    }
}

icons.sort((a, b) => a.name < b.name ? -1 : a.name > b.name ? 1 : 0);

const php = `<?php

declare(strict_types=1);

namespace Anodyne\\DisartoIcons;

// Generated by bun run build. Do not edit manually.
enum DisartoIcon: string
{
${icons.map(({ name, caseName }) => `    case ${caseName} = 'disarto-${name}';`).join('\n')}
}
`;

await mkdir(destination, { recursive: true });
for (const { name, svg } of icons) {
    await writeFile(join(destination, `${name}.svg`), `${svg}\n`);
}

// Remove icons that were removed or renamed upstream.
for (const file of await readdir(destination, { withFileTypes: true })) {
    if (file.isFile() && file.name.endsWith('.svg') && !filenames.has(file.name.slice(0, -4))) {
        await unlink(join(destination, file.name));
    }
}

await writeFile(join(root, 'src/DisartoIcon.php'), php);
console.log(`Compiled and optimized ${icons.length} SVG icons and generated src/DisartoIcon.php.`);
